import{_ as n,o as e,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"威胁模型与信任边界","description":"识别 Agent 系统的资产、参与者、数据流和信任边界，用滥用案例与风险优先级选择可验证控制措施。","frontmatter":{"title":"威胁模型与信任边界","description":"识别 Agent 系统的资产、参与者、数据流和信任边界，用滥用案例与风险优先级选择可验证控制措施。","verified_at":"2026-07-31","source":["https://genai.owasp.org/llm-top-10/","https://atlas.mitre.org/","https://www.nist.gov/itl/ai-risk-management-framework","https://owasp.org/www-community/Threat_Modeling"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/quality/security-governance/threat-model-trust-boundaries.md","filePath":"py-agent/quality/security-governance/threat-model-trust-boundaries.md","lastUpdated":1785589115000}'),l={name:"py-agent/quality/security-governance/threat-model-trust-boundaries.md"};function i(r,a,p,o,d,h){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="威胁模型与信任边界" tabindex="-1">威胁模型与信任边界 <a class="header-anchor" href="#威胁模型与信任边界" aria-label="Permalink to &quot;威胁模型与信任边界&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 安全不能从“加一个内容过滤器”开始。Agent 会读取不可信内容、调用有副作用的工具、保存长期状态，并代表用户访问外部系统；必须先知道要保护什么、谁可能攻击、数据跨越了哪些边界，才能判断控制措施是否有效。</p><h2 id="_1-威胁模型的产物" tabindex="-1">1. 威胁模型的产物 <a class="header-anchor" href="#_1-威胁模型的产物" aria-label="Permalink to &quot;1. 威胁模型的产物&quot;">​</a></h2><h3 id="_1-1-范围" tabindex="-1">1.1 范围 <a class="header-anchor" href="#_1-1-范围" aria-label="Permalink to &quot;1.1 范围&quot;">​</a></h3><p>先写明本次建模覆盖的系统版本、环境、租户、数据和外部集成。一个客服只读问答 Agent 与能够退款、发邮件的执行 Agent，风险面完全不同。</p><h3 id="_1-2-四类核心产物" tabindex="-1">1.2 四类核心产物 <a class="header-anchor" href="#_1-2-四类核心产物" aria-label="Permalink to &quot;1.2 四类核心产物&quot;">​</a></h3><ol><li>资产清单：什么一旦泄露、篡改或不可用会造成损失；</li><li>数据流图：数据、指令和权限如何在组件间流动；</li><li>威胁与滥用案例：攻击者如何破坏安全目标；</li><li>控制与验证：在哪里阻止、检测、响应，以及如何证明。</li></ol><p>威胁模型不是一次性的文档。工具、数据源、模型、权限或部署边界变化时都要更新。</p><h2 id="_2-资产与安全目标" tabindex="-1">2. 资产与安全目标 <a class="header-anchor" href="#_2-资产与安全目标" aria-label="Permalink to &quot;2. 资产与安全目标&quot;">​</a></h2><h3 id="_2-1-资产" tabindex="-1">2.1 资产 <a class="header-anchor" href="#_2-1-资产" aria-label="Permalink to &quot;2.1 资产&quot;">​</a></h3><p>Agent 系统常见资产包括：</p><ul><li>用户消息、上传文件、记忆和个人数据；</li><li>系统提示词、政策、工具描述和内部知识；</li><li>API Key、数据库凭据和委托 Token；</li><li>工具能力，如付款、删除、发送和代码执行；</li><li>模型、索引、Checkpoint、评测数据和审计记录；</li><li>计算、Token、带宽和第三方额度；</li><li>用户信任、业务正确性和服务可用性。</li></ul><p>“系统提示词是否需要保密”取决于其中是否含秘密。提示词本身不能充当访问控制；真正的 Secret 不应放入模型上下文。</p><h3 id="_2-2-安全目标" tabindex="-1">2.2 安全目标 <a class="header-anchor" href="#_2-2-安全目标" aria-label="Permalink to &quot;2.2 安全目标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>目标</th><th>Agent 场景</th></tr></thead><tbody><tr><td>机密性</td><td>A 租户不能读到 B 租户数据</td></tr><tr><td>完整性</td><td>文档不能篡改工具参数或长期记忆</td></tr><tr><td>可用性</td><td>恶意循环不能耗尽模型额度</td></tr><tr><td>授权</td><td>模型建议不能替代服务端权限判断</td></tr><tr><td>可追责性</td><td>高风险动作能追溯主体、依据和结果</td></tr><tr><td>隐私</td><td>数据用途、保留和删除符合承诺</td></tr></tbody></table><h2 id="_3-参与者与能力" tabindex="-1">3. 参与者与能力 <a class="header-anchor" href="#_3-参与者与能力" aria-label="Permalink to &quot;3. 参与者与能力&quot;">​</a></h2><h3 id="_3-1-外部参与者" tabindex="-1">3.1 外部参与者 <a class="header-anchor" href="#_3-1-外部参与者" aria-label="Permalink to &quot;3.1 外部参与者&quot;">​</a></h3><p>包括正常用户、恶意用户、被攻陷账户、第三方内容发布者、工具服务和模型供应商。攻击者不一定直接与 Agent 对话，也可能把指令藏在网页、邮件或知识库文档中。</p><h3 id="_3-2-内部参与者" tabindex="-1">3.2 内部参与者 <a class="header-anchor" href="#_3-2-内部参与者" aria-label="Permalink to &quot;3.2 内部参与者&quot;">​</a></h3><p>管理员、标注者、运维人员、开发者和自动化发布系统都有不同权限。内部身份不等于完全可信，需最小权限、职责分离和审计。</p><h3 id="_3-3-模型不是安全主体" tabindex="-1">3.3 模型不是安全主体 <a class="header-anchor" href="#_3-3-模型不是安全主体" aria-label="Permalink to &quot;3.3 模型不是安全主体&quot;">​</a></h3><p>模型不能可靠保管 Secret、做最终授权或证明内容可信。它是处理不可信输入的概率性组件。安全决策应由确定性策略引擎、身份系统和工具执行层实施。</p><h2 id="_4-数据流与信任边界" tabindex="-1">4. 数据流与信任边界 <a class="header-anchor" href="#_4-数据流与信任边界" aria-label="Permalink to &quot;4. 数据流与信任边界&quot;">​</a></h2><h3 id="_4-1-典型数据流" tabindex="-1">4.1 典型数据流 <a class="header-anchor" href="#_4-1-典型数据流" aria-label="Permalink to &quot;4.1 典型数据流&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User/Client</span></span>
<span class="line"><span>   | identity + input</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>API/Auth Boundary</span></span>
<span class="line"><span>   | trusted principal + untrusted content</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>Agent Runtime &lt;------ Retrieved documents / memory</span></span>
<span class="line"><span>   | proposed tool call          ^</span></span>
<span class="line"><span>   v                             |</span></span>
<span class="line"><span>Policy &amp; Tool Gateway ------ Data stores</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>External systems / Sandbox</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>箭头同时携带数据、指令或权限。每条边都应记录数据分类、认证方式、授权依据、完整性保护、日志和失败行为。</p><h3 id="_4-2-常见边界" tabindex="-1">4.2 常见边界 <a class="header-anchor" href="#_4-2-常见边界" aria-label="Permalink to &quot;4.2 常见边界&quot;">​</a></h3><ul><li>互联网与 API 网关；</li><li>已认证用户与服务端 Principal；</li><li>普通文本与系统指令；</li><li>Agent Runtime 与工具执行器；</li><li>一个租户与另一个租户；</li><li>应用与模型供应商；</li><li>主机与代码 Sandbox；</li><li>在线系统与日志、分析、标注平台。</li></ul><p>同一进程内也可能存在信任边界。是否跨网络不是唯一标准，权限和数据所有权变化才是关键。</p><h2 id="_5-威胁分类" tabindex="-1">5. 威胁分类 <a class="header-anchor" href="#_5-威胁分类" aria-label="Permalink to &quot;5. 威胁分类&quot;">​</a></h2><h3 id="_5-1-输入与指令完整性" tabindex="-1">5.1 输入与指令完整性 <a class="header-anchor" href="#_5-1-输入与指令完整性" aria-label="Permalink to &quot;5.1 输入与指令完整性&quot;">​</a></h3><p>直接或间接 Prompt Injection 诱导模型忽略政策、泄露上下文或调用工具。输入过滤能降低已知模式风险，但无法证明自然语言中不存在恶意指令。</p><h3 id="_5-2-工具与权限" tabindex="-1">5.2 工具与权限 <a class="header-anchor" href="#_5-2-工具与权限" aria-label="Permalink to &quot;5.2 工具与权限&quot;">​</a></h3><p>过度授权、参数混淆、服务端请求伪造、路径穿越、命令注入和重复副作用。模型只应提出动作，工具网关必须重新校验主体、资源、参数和业务前置条件。</p><h3 id="_5-3-数据与记忆" tabindex="-1">5.3 数据与记忆 <a class="header-anchor" href="#_5-3-数据与记忆" aria-label="Permalink to &quot;5.3 数据与记忆&quot;">​</a></h3><p>跨租户检索、敏感信息进入模型或日志、恶意内容污染长期记忆、删除请求未传播到派生存储。向量相似度不是授权机制。</p><h3 id="_5-4-输出与下游消费" tabindex="-1">5.4 输出与下游消费 <a class="header-anchor" href="#_5-4-输出与下游消费" aria-label="Permalink to &quot;5.4 输出与下游消费&quot;">​</a></h3><p>模型输出进入 HTML、SQL、Shell、模板或另一个 Agent 时可能成为注入载荷。输出必须按下游语境编码和验证，不能因为来自模型就视为可信。</p><h3 id="_5-5-资源与供应链" tabindex="-1">5.5 资源与供应链 <a class="header-anchor" href="#_5-5-资源与供应链" aria-label="Permalink to &quot;5.5 资源与供应链&quot;">​</a></h3><p>无限循环、超长输入、工具扇出和昂贵路由会耗尽预算；模型、依赖包、容器、插件和数据集也可能被篡改。需要预算、来源验证、版本锁定和制品签名。</p><h2 id="_6-滥用案例" tabindex="-1">6. 滥用案例 <a class="header-anchor" href="#_6-滥用案例" aria-label="Permalink to &quot;6. 滥用案例&quot;">​</a></h2><p>滥用案例用攻击者目标描述，而不是列产品名：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>作为能上传文档的普通租户用户，</span></span>
<span class="line"><span>我把“读取其他租户客户列表并发送到指定 URL”藏入 PDF，</span></span>
<span class="line"><span>希望检索后的内容被 Agent 当作高优先级指令，</span></span>
<span class="line"><span>从而越过租户和网络出口限制。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这个案例对应多个可验证控制：检索时强制租户过滤、内容作为不可信数据标记、工具层重新授权、网络出口 Allowlist、敏感字段检测和动作审计。单一 Prompt 提醒不是充分控制。</p><h2 id="_7-风险排序" tabindex="-1">7. 风险排序 <a class="header-anchor" href="#_7-风险排序" aria-label="Permalink to &quot;7. 风险排序&quot;">​</a></h2><h3 id="_7-1-风险因素" tabindex="-1">7.1 风险因素 <a class="header-anchor" href="#_7-1-风险因素" aria-label="Permalink to &quot;7.1 风险因素&quot;">​</a></h3><p>考虑发生可能性、影响、可发现性和暴露范围。高权限写工具、不可逆副作用、敏感数据和公网输入会提高优先级。</p><h3 id="_7-2-不要伪装精确" tabindex="-1">7.2 不要伪装精确 <a class="header-anchor" href="#_7-2-不要伪装精确" aria-label="Permalink to &quot;7.2 不要伪装精确&quot;">​</a></h3><p><code>风险 = 可能性 × 影响</code> 可帮助排序，但 1-5 分不是客观概率。保存评分理由、证据和假设，比追求小数点更重要。</p><h3 id="_7-3-风险处置" tabindex="-1">7.3 风险处置 <a class="header-anchor" href="#_7-3-风险处置" aria-label="Permalink to &quot;7.3 风险处置&quot;">​</a></h3><ul><li>Avoid：移除能力，例如不开放任意代码执行；</li><li>Reduce：最小权限、确认、隔离、验证和监控；</li><li>Transfer：合同或保险只转移部分损失，不转移责任；</li><li>Accept：由有权限的责任人接受剩余风险并设置复查日期。</li></ul><h2 id="_8-控制映射" tabindex="-1">8. 控制映射 <a class="header-anchor" href="#_8-控制映射" aria-label="Permalink to &quot;8. 控制映射&quot;">​</a></h2><h3 id="_8-1-预防、检测与响应" tabindex="-1">8.1 预防、检测与响应 <a class="header-anchor" href="#_8-1-预防、检测与响应" aria-label="Permalink to &quot;8.1 预防、检测与响应&quot;">​</a></h3><p>每个高风险威胁至少要考虑三层：预防攻击成功，检测可疑行为，发生后限制影响并恢复。例如工具越权：策略引擎拒绝是预防，异常调用告警是检测，撤销 Token 与补偿动作是响应。</p><h3 id="_8-2-控制所有者" tabindex="-1">8.2 控制所有者 <a class="header-anchor" href="#_8-2-控制所有者" aria-label="Permalink to &quot;8.2 控制所有者&quot;">​</a></h3><p>控制必须落到组件：API 网关负责认证，应用建立可信 Principal，策略层授权，Sandbox 隔离执行，数据层实施租户过滤，观测层保留审计。把所有责任写成“Agent 应防止”没有可执行性。</p><h3 id="_8-3-验证方式" tabindex="-1">8.3 验证方式 <a class="header-anchor" href="#_8-3-验证方式" aria-label="Permalink to &quot;8.3 验证方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>控制</th><th>验证</th></tr></thead><tbody><tr><td>租户隔离</td><td>跨租户负面集成测试</td></tr><tr><td>工具最小权限</td><td>策略单测 + 运行角色审计</td></tr><tr><td>Prompt Injection 防护</td><td>对抗评测 + 工具轨迹检查</td></tr><tr><td>预算限制</td><td>循环/扇出故障测试</td></tr><tr><td>Secret 管理</td><td>镜像与日志扫描 + 轮换演练</td></tr><tr><td>恢复</td><td>备份还原与凭据撤销演练</td></tr></tbody></table><h2 id="_9-填写后的最小记录" tabindex="-1">9. 填写后的最小记录 <a class="header-anchor" href="#_9-填写后的最小记录" aria-label="Permalink to &quot;9. 填写后的最小记录&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>资产：租户客户资料、邮件发送能力</span></span>
<span class="line"><span>边界：检索内容 -&gt; Agent Runtime -&gt; 邮件工具</span></span>
<span class="line"><span>攻击者：可上传知识库文档的租户成员</span></span>
<span class="line"><span>威胁：文档中的间接注入诱导批量外发资料</span></span>
<span class="line"><span>现有控制：租户检索过滤、邮件域 Allowlist、单次收件人数限制</span></span>
<span class="line"><span>剩余风险：允许域内仍可能误发敏感字段</span></span>
<span class="line"><span>新增控制：字段级 DLP、发送前预览与人工确认、审计告警</span></span>
<span class="line"><span>验证：20 个注入样本零未授权发送；确认绕过集成测试必须失败</span></span>
<span class="line"><span>所有者：应用安全负责人</span></span>
<span class="line"><span>复查：新增邮件能力或权限模型变化时</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="_10-常见误区" tabindex="-1">10. 常见误区 <a class="header-anchor" href="#_10-常见误区" aria-label="Permalink to &quot;10. 常见误区&quot;">​</a></h2><ol><li><strong>从 OWASP 清单直接抄控制</strong>：没有映射当前资产和数据流。</li><li><strong>把系统提示词当安全边界</strong>：它与不可信文本最终都由模型处理。</li><li><strong>只考虑恶意用户输入</strong>：网页、RAG 文档、工具结果和记忆同样不可信。</li><li><strong>只做预防不做检测和恢复</strong>：任何一层控制都有失效可能。</li><li><strong>上线前做一次就结束</strong>：新增工具或模型路由会改变风险。</li></ol><h2 id="_11-评审清单" tabindex="-1">11. 评审清单 <a class="header-anchor" href="#_11-评审清单" aria-label="Permalink to &quot;11. 评审清单&quot;">​</a></h2><ul><li>范围、资产、参与者和安全目标是否明确；</li><li>所有数据、指令和权限跨界点是否可见；</li><li>直接输入与间接内容是否都按不可信处理；</li><li>每个高风险滥用案例是否有预防、检测和响应；</li><li>控制是否有组件所有者和可执行验证；</li><li>剩余风险是否由有权限的人接受并设置复查条件。</li></ul><p>威胁模型的价值不是预测所有攻击，而是让安全假设显式化：什么可信、为什么可信、失效后由哪一层控制兜底，以及如何证明这些控制真的存在。</p>`,66)])])}const b=n(l,[["render",i]]);export{u as __pageData,b as default};
